   "Back positioning is appropriate, but a loose blanket still creates a sleep hazard. Use a clear, firm, flat sleep surface and appropriate sleep clothing.",
   "Adult presence does not remove the sleep-related risks of prone placement. The usual safe-sleep recommendations still apply."
